def autoscale_step(avg_cpu, current, minimum, maximum, scale_out_at=70.0, scale_in_at=30.0):
    if avg_cpu > scale_out_at and current < maximum:
        return current + 1
    if avg_cpu < scale_in_at and current > minimum:
        return current - 1
    return current

cpu_samples = [42.0, 55.0, 78.0, 82.0, 74.0, 61.0, 28.0, 25.0]
instances = 2
minimum, maximum = 2, 5
history = [instances]

for reading in cpu_samples:
    instances = autoscale_step(reading, instances, minimum, maximum)
    history.append(instances)

labels = ["start"] + [f"{c:.0f}%" for c in cpu_samples]
for label, count in zip(labels, history):
    print(f"{label:>6} -> {count} instancias")
